contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function performing the property-based test
    // take a dummy uint to vary inputs (no Ether needed)
    function run(uint256 dummy) public payable {
        // record balance of c before the call
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        // Call sudicideAnyone as this contract (which is the owner of c because the harness deploys c with this contract as msg.sender)
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = address(c).balance;

        // General rule: whenever the owner-call does not revert, C's balance must be zero afterwards.
        // This asserts the invariant for all inputs: reverted || afterBalance == 0
        assert(reverted || afterBalance == 0);
    }

    // accept Ether if sent by selfdestruct in some runs
    receive() external payable {}
}

